  "guardrail_code": "import posixpath
import urllib.parse
import unicodedata

def enforce_policy(session_log: list[dict], proposed_call: dict) -> dict:
    server = proposed_call.get('server')
    tool = proposed_call.get('tool')
    args = proposed_call.get('args', {})
    tenant_id = proposed_call.get('tenant_id')
    jwt_aud = proposed_call.get('jwt_aud')

    # Manifest data
    server_manifest = {
        'billing-mcp': {
            'trust_level': 'internal_service',
            'uri': 'mcp://billing-mcp'
        },
        'vault-mcp': {
            'trust_level': 'privileged_secrets',
            'uri': 'mcp://vault-mcp',
            'allowed_secret_prefixes': ['app/billing/', 'app/shared/']
        }
    }

    # Clause 0: Token audience
    expected_aud = server_manifest.get(server, {}).get('uri')
    if expected_aud and jwt_aud != expected_aud:
        return {'allow': False, 'reason': 'jwt_aud mismatch'}

    # Clause 1: Exfiltration to less-trusted server
    target_trust = server_manifest.get(server, {}).get('trust_level')
    if target_trust in ('untrusted_third_party', 'untrusted_external'):
        def extract_strings(obj):
            strings = []
            if isinstance(obj, str) and len(obj) >= 4:
                strings.append(obj)
            elif isinstance(obj, dict):
                for v in obj.values():
                    strings.extend(extract_strings(v))
            elif isinstance(obj, list):
                for item in obj:
                    strings.extend(extract_strings(item))
            return strings

        arg_strings = extract_strings(args)
        for s in arg_strings:
            if s.startswith('postgres://') or s.startswith('postgresql://'):
                return {'allow': False, 'reason': 'database URI in args to untrusted server'}

        # Collect qualifying strings from privileged server outputs
        privileged_trust = {'privileged_internal', 'privileged_cloud', 'privileged_secrets', 'privileged_financial', 'privileged_local'}
        tainted_strings = set()
        for entry in session_log:
            entry_server = entry.get('server')
            entry_trust = server_manifest.get(entry_server, {}).get('trust_level')
            if entry_trust in privileged_trust:
                output = entry.get('output', {})
                tainted_strings.update(extract_strings(output))

        for s in arg_strings:
            for tainted in tainted_strings:
                if tainted in s:
                    return {'allow': False, 'reason': 'tainted data from privileged server in args'}

    # Clause 2: Unapproved schema change
    manifest_entry = server_manifest.get(server, {})
    approved_domain = manifest_entry.get('approved_domain')
    if approved_domain:
        for key, value in args.items():
            if key == 'webhook_url' or key.endswith('_url'):
                if not isinstance(value, str) or not value.startswith(approved_domain):
                    return {'allow': False, 'reason': f'{key} not under approved_domain'}
                # Check for tools/list_changed without reapproval
                changed = False
                for entry in session_log:
                    if entry.get('type') == 'notifications/tools/list_changed' and entry.get('server') == server:
                        changed = True
                    if entry.get('type') == 'admin/reapprove_schema' and entry.get('server') == server:
                        changed = False
                if changed:
                    return {'allow': False, 'reason': 'schema changed without reapproval'}

    # Clause 3: Untrusted fragments in role ARN
    if server == 'aws-iam-mcp' and tool == 'assume_role':
        role_arn = args.get('role_arn')
        allowed_prefix = manifest_entry.get('allowed_arn_prefix')
        if not isinstance(role_arn, str) or not role_arn.startswith(allowed_prefix):
            return {'allow': False, 'reason': 'role_arn not under allowed_arn_prefix'}
        # Check for tainted strings from untrusted_external
        tainted_strings = set()
        for entry in session_log:
            entry_server = entry.get('server')
            entry_trust = server_manifest.get(entry_server, {}).get('trust_level')
            if entry_trust == 'untrusted_external':
                output = entry.get('output', {})
                tainted_strings.update(extract_strings(output))
        for tainted in tainted_strings:
            if tainted in role_arn:
                return {'allow': False, 'reason': 'tainted fragment in role_arn'}

    # Clause 4: Secret path scope
    if server == 'vault-mcp' and tool == 'read_secret':
        secret_path = args.get('secret_path')
        allowed_prefixes = manifest_entry.get('allowed_secret_prefixes', [])
        if not isinstance(secret_path, str) or not any(secret_path.startswith(p) for p in allowed_prefixes):
            return {'allow': False, 'reason': 'secret_path not under allowed prefix'}

    # Clause 5: Canonical path boundary
    if server == 'filesystem-mcp' and tool in ('read_file', 'write_file'):
        allowed_root = manifest_entry.get('allowed_root')
        if allowed_root:
            path = args.get('path')
            if not isinstance(path, str) or not path:
                return {'allow': False, 'reason': 'path must be non-empty string'}
            # Double URL decode
            decoded = urllib.parse.unquote(urllib.parse.unquote(path))
            # NFKC normalize
            normalized = unicodedata.normalize('NFKC', decoded)
            # POSIX normpath
            norm_path = posixpath.normpath(normalized)
            root = allowed_root.rstrip('/')
            if not (norm_path == root or norm_path.startswith(root + '/')):
                return {'allow': False, 'reason': 'path outside allowed_root'}

    # Clause 6: Explicit tenant account
    connection_mode = manifest_entry.get('connection_mode')
    if connection_mode == 'shared_persistent_sse':
        account_scoped = manifest_entry.get('account_scoped_tools', [])
        if tool in account_scoped:
            account_id = args.get('account_id')
            expected = f'acct_{tenant_id}' if tenant_id else None
            if not isinstance(account_id, str) or not account_id or account_id != expected:
                return {'allow': False, 'reason': 'account_id missing or mismatched tenant'}

    # Clause 7: Declared argument types
    typed_args = manifest_entry.get('typed_arguments', {}).get(tool, [])
    for spec in typed_args:
        name = spec.get('name')
        if name not in args:
            continue
        val = args[name]
        if spec.get('type') == 'string':
            if not isinstance(val, str):
                return {'allow': False, 'reason': f'{name} must be string'}
            if 'enum' in spec and val not in spec['enum']:
                return {'allow': False, 'reason': f'{name} value not in enum'}
            if 'prefixes' in spec and not any(val.startswith(p) for p in spec['prefixes']):
                return {'allow': False, 'reason': f'{name} missing required prefix'}

    # Clause 8: Hotfix constraints for github-mcp
    if server == 'github-mcp' and tool == 'create_hotfix_branch':
        constraints = manifest_entry.get('hotfix_constraints', {})
        repo = args.get('repo')
        branch = args.get('branch')
        repo_prefix = constraints.get('repo_prefix')
        repo_suffix = constraints.get('repo_suffix')
        branch_prefix = constraints.get('branch_prefix')
        if not (isinstance(repo, str) and repo.startswith(repo_prefix) and repo.endswith(repo_suffix)):
            return {'allow': False, 'reason': 'repo does not match hotfix constraints'}
        if not (isinstance(branch, str) and branch.startswith(branch_prefix)):
            return {'allow': False, 'reason': 'branch does not match hotfix constraints'}

    return {'allow': True, 'reason': 'allowed'}"
}
